package pe.edu.cacaoselva.desktop;
import javafx.application.Application; import javafx.scene.Scene; import javafx.stage.Stage; import pe.edu.cacaoselva.application.port.LoteQueryPort; import pe.edu.cacaoselva.infrastructure.http.HttpLoteQueryAdapter; import pe.edu.cacaoselva.desktop.view.LoteView; import pe.edu.cacaoselva.desktop.controller.LoteDesktopController; import java.net.URI; import java.net.http.HttpClient; import java.time.Duration;
public class CacaoSelvaDesktopApplication extends Application { private static final String API_URL="http://localhost:5080/lotes"; public void start(Stage stage){HttpClient client=HttpClient.newBuilder().connectTimeout(Duration.ofSeconds(3)).build(); LoteQueryPort port=new HttpLoteQueryAdapter(client,URI.create(API_URL)); LoteView view=new LoteView(); new LoteDesktopController(view,port); stage.setTitle("CacaoSelva - Desktop"); stage.setScene(new Scene(view,720,430)); stage.show();} public static void main(String[] args){launch(args);} }
